//! DuckDB parity against upstream R (DatabaseConnector 8.0.0, R `duckdb` 2.0.0, engine v2.0.0),
//! generated by `tests/oracle/duckdb-cases.R`: the database scenarios of `database-cases.R`, the
//! `cdm_source` preflights, upstream's "Execute a single DQ check on DuckDB" test, and a full
//! GiBleed run.
use data_quality_dashboard::{database, model::Options, results, runner, sql::NativeSql};
use serde_json::{Map, Value};
use std::{fs, path::Path};

mod common;
use common::*;

const SCENARIOS: [&str; 8] = [
    "clean",
    "violating",
    "missing-table",
    "missing-field",
    "empty-table",
    "unpopulated-field",
    "cohort",
    "clean-write-table",
];

fn cases() -> Value {
    fixture("duckdb/expected.json")
}

/// Copies a fixture database: every run gets a fresh file, as the oracle did.
fn working_copy(fixture: &str, dir: &Path) -> String {
    let working = dir.join("cdm.duckdb");
    fs::copy(oracle().join(fixture), &working).unwrap();
    working.to_string_lossy().into_owned()
}

fn duckdb_options(mut options: Options, db: String, folder: &Path) -> Options {
    options.dbms = "duckdb".into();
    options.connection.server = Some(db);
    options.output_folder = folder.to_path_buf();
    options
}

/// DuckDB tables DQD wrote, keyed `schema.table` as the oracle lists them; `execution_time` varies.
fn dqd_tables(options: &Options) -> Value {
    let mut connection = database::connect(options).unwrap();
    let names = connection
        .query("SELECT table_schema, table_name FROM information_schema.tables ORDER BY 1, 2")
        .unwrap();
    let mut tables = Map::new();
    for row in names {
        let (schema, table) = (
            row["table_schema"].as_str().unwrap(),
            row["table_name"].as_str().unwrap(),
        );
        if !table.contains("dqdashboard") {
            continue;
        }
        let rows = connection
            .query(&format!("SELECT * FROM \"{schema}\".\"{table}\""))
            .unwrap();
        tables.insert(
            format!("{schema}.{table}"),
            Value::Array(
                rows.into_iter()
                    .map(|mut row| {
                        row.remove("execution_time");
                        Value::Object(row)
                    })
                    .collect(),
            ),
        );
    }
    Value::Object(tables)
}

fn without_execution_time(mut tables: Value) -> Value {
    for rows in tables
        .as_object_mut()
        .into_iter()
        .flat_map(|t| t.values_mut())
    {
        for row in rows.as_array_mut().into_iter().flatten() {
            row.as_object_mut().unwrap().remove("execution_time");
        }
    }
    tables
}

#[test]
fn duckdb_database_runs_match_upstream_check_rows_tables_and_csv() {
    let cases = cases();
    for name in SCENARIOS {
        let case = &cases[name];
        let dir = tempfile::tempdir().unwrap();
        let db = working_copy(case["duckdb"].as_str().unwrap(), dir.path());
        let options = duckdb_options(
            case_options(&case["options"]),
            db,
            &dir.path().join("results"),
        );
        assert!(case["expected"]["ok"].as_bool().unwrap(), "{name} oracle");
        let actual = run_and_read_results_file(name, &options);
        assert_results_match(name, &actual, &case["result"]);
        let actual_csv = fs::read_to_string(options.output_folder.join(&options.csv_file)).unwrap();
        let expected_csv = string_vector(&case["resultCsv"]).join("\n");
        assert_eq!(
            csv_records(&actual_csv),
            csv_records(&expected_csv),
            "{name} CSV"
        );
        if name == "clean-write-table" {
            assert_json_equal(
                &dqd_tables(&options),
                &without_execution_time(case["tableRows"].clone()),
                "write-to-table",
            );
            let mut connection = database::connect(&options).unwrap();
            let json_folder = dir.path().join("db-json");
            fs::create_dir_all(&json_folder).unwrap();
            results::write_db_results_to_json(
                connection.as_mut(),
                &mut NativeSql::new(),
                "duckdb",
                "main",
                "main",
                "dqdashboard_results",
                &json_folder,
                "from-database.json",
            )
            .unwrap();
            assert!(case["databaseJsonExpected"]["ok"].as_bool().unwrap());
            let mut actual = read_json(&json_folder.join("from-database.json"));
            let mut expected = case["databaseJson"].clone();
            strip_volatile(&mut actual);
            strip_volatile(&mut expected);
            assert_json_equal(&actual, &expected, "write-db-results-to-json");
        }
    }
}

#[test]
fn duckdb_cdm_source_preflight_failures_match_upstream() {
    let cases = cases();
    for name in ["empty-cdm-source", "missing-cdm-source"] {
        let case = &cases[name];
        let dir = tempfile::tempdir().unwrap();
        let db = working_copy(case["duckdb"].as_str().unwrap(), dir.path());
        let options = duckdb_options(
            Options {
                cdm_database_schema: "main".into(),
                results_database_schema: "main".into(),
                vocab_database_schema: "main".into(),
                cohort_database_schema: "main".into(),
                cdm_source_name: "Parity".into(),
                ..Options::default()
            },
            db,
            &dir.path().join("results"),
        );
        let expected = case["expected"]["error"].as_str().unwrap();
        let actual = format!("{:#}", runner::execute_dq_checks(&options).unwrap_err());
        let _ = fs::remove_file("errorReportSql.txt");
        let report = |text: &str| -> String {
            match text.split_once("An error report has been created at  ") {
                Some((prefix, _)) => format!("{prefix}<report>"),
                None => text.to_owned(),
            }
        };
        assert_eq!(report(&actual), report(expected), "{name}");
    }
}

#[test]
fn duckdb_single_check_matches_upstream_test() {
    let case = &cases()["single-check"];
    let dir = tempfile::tempdir().unwrap();
    let db = working_copy("duckdb/gibleed/cdm.duckdb", dir.path());
    let options = duckdb_options(
        case_options(&case["options"]),
        db,
        &dir.path().join("results"),
    );
    let actual = run_and_read_results_file("duckdb single check", &options);
    assert!(actual["CheckResults"].as_array().unwrap().len() > 0);
    assert_results_match("duckdb single check", &actual, &case["result"]);
}

#[test]
fn duckdb_gibleed_run_matches_upstream_results_and_csv() {
    let folder = oracle().join("duckdb/gibleed");
    let expected = read_json(&folder.join("results.json"));
    let timing = read_json(&folder.join("timing.json"));
    assert_eq!(timing["status_counts"]["error"], 0);
    // The oracle's single worker, then parallel workers sharing one DuckDB instance.
    for threads in [1.0, 8.0] {
        let name = format!("duckdb gibleed threads={threads}");
        let dir = tempfile::tempdir().unwrap();
        let db = working_copy("duckdb/gibleed/cdm.duckdb", dir.path());
        let mut options = duckdb_options(
            case_options(&read_json(&folder.join("options.json"))),
            db,
            &dir.path().join("results"),
        );
        options.num_threads = threads;
        let actual = run_and_read_results_file(&name, &options);
        assert_results_match(&name, &actual, &expected);
        let actual_csv = fs::read_to_string(options.output_folder.join(&options.csv_file)).unwrap();
        let expected_csv = fs::read_to_string(folder.join(&options.csv_file)).unwrap();
        assert_eq!(
            csv_records(&actual_csv),
            csv_records(&expected_csv),
            "{name} CSV"
        );
    }
}
